const sp = req.nextUrl.searchParams
const q = sp.get('q')?.trim().toLowerCase() ?? ''
const kind = sp.get('kind') ?? 'all'
const status = sp.get('status') ?? 'all'
const sort = sp.get('sort') ?? 'updatedAt'
const order = sp.get('order') ?? 'desc'
const where: { OR?: { name: { contains: string } }[]; category?: string } = {}
if (q) where.OR = [{ name: { contains: q } }]
if (status && status !== 'all') where.status = status
if (kind && kind !== 'all') where.category = kind
let rows = await db.inventoryItem.findMany({ where, orderBy:
 sort === 'name' ? { name: order } : sort === 'quantity' ?
 { quantity: order } : { updatedAt: order } })
if (status === 'low' || status === 'out') rows = rows.filter((a) => a.quantity > 0 && a.quantity <= minQuantity)
if (status === 'ok') rows = rows.filter((a) => a.quantity > minQuantity)
const items = rows.map((a) => ({ ...a, updatedAt: a.updatedAt.toISOString() }))
return NextResponse.json({ items, total: items.length })
